select a.competition_track_config_id, a.competition_track_id, a.competition_track_type, a.second_level_code, a.second_level_name,
b.config_id,b.competition_track_config_id, b.join_type, b.is_teacher_ness,
b.min_pern_num, b.max_pern_num, b.min_teacher_num, b.max_teacher_num, b.team_rule, b.is_real_name_auth, b.is_student,
b.is_nationality_student, b.class_request, b.profession_request, b.lowest_gpa, b.works_submit_way,b.works_format,
b.works_format_size,b.works_submit_date,b.works_submit_explain,b.apply_start_time,b.apply_end_time,b.fee,
a.create_by, a.create_time, a.update_by, a.update_time, a.version, a.del_flag
from competition_track_config a
left join competition_config b on a.competition_track_config_id = b.competition_track_config_id
where a.del_flag = '0'
     and competition_track_id = #{competitionTrackId}
     and competition_group_code = #{competitionGroupCode}
     and competition_item_code = #{competitionItemCode}
     and subsidiary_subject_code = #{subsidiarySubjectCode}
     and competition_group = #{competitionGroup}
     and competition_item = #{competitionItem}
     and subsidiary_subject = #{subsidiarySubject}
     and competition_group_name like concat('%', #{competitionGroupName}, '%')
     and competition_item_name like concat('%', #{competitionItemName}, '%')
     and subsidiary_subject_name like concat('%', #{subsidiarySubjectName}, '%')

select a.competition_track_config_id, a.competition_track_id, a.competition_track_type, a.second_level_code, a.second_level_name, b.config_id,b.competition_track_config_id, b.join_type, b.is_teacher_ness,t.check_package_id, b.min_pern_num, b.max_pern_num, b.min_teacher_num, b.max_teacher_num, b.team_rule, b.is_real_name_auth, b.is_student, b.is_nationality_student, b.class_request, b.profession_request, b.lowest_gpa, b.works_submit_way,b.works_format, b.works_format_size,b.works_submit_date,b.works_submit_explain,b.apply_start_time,b.apply_end_time,b.fee, a.create_by, a.create_time, a.update_by, a.update_time, a.version, a.del_flag from competition_track_config a left join competition_track_info t on t.competition_track_id = a.competition_track_id left join competition_config b on a.competition_track_config_id = b.competition_track_config_id where a.del_flag = '0'
and a.competition_track_config_id = #{competitionTrackConfigId}
and a.second_level_code = #{secondLevelCode}
and t.check_status = #{checkStatus}

select a.competition_track_config_id, a.competition_track_id, a.competition_track_type, a.second_level_code, a.second_level_name, b.config_id,b.competition_track_config_id, b.join_type, b.is_teacher_ness, b.min_pern_num, b.max_pern_num, b.min_teacher_num, b.max_teacher_num, b.team_rule, b.is_real_name_auth, b.is_student, b.is_nationality_student, b.class_request, b.profession_request, b.lowest_gpa, b.works_submit_way,b.works_format, b.works_format_size,b.works_submit_date,b.works_submit_explain,b.apply_start_time,b.apply_end_time,b.fee, a.create_by, a.create_time, a.update_by, a.update_time, a.version, a.del_flag from competition_track_config a left join competition_track_info t on t.competition_track_id = a.competition_track_id left join competition_config b on a.competition_track_config_id = b.competition_track_config_id where a.del_flag = '0'
and t.competition_series_id = #{competitionSeriesId}
and a.competition_track_id in
#{item}
