update competition_track_config
competition_track_id = #{competitionTrackId}, competition_track_type = #{competitionTrackType}, second_level_code = #{secondLevelCode}, second_level_name = #{secondLevelName}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = #{version},
where competition_track_config_id = #{competitionTrackConfigId}

update competition_track_config
competition_track_id = CASE
WHEN competition_track_config_id = #{item.competitionTrackConfigId} THEN #{item.competitionTrackId}
ELSE competition_track_id END,
competition_track_type = CASE
WHEN competition_track_config_id = #{item.competitionTrackConfigId} THEN #{item.competitionTrackType}
ELSE competition_track_type END,
second_level_code = CASE
WHEN competition_track_config_id = #{item.competitionTrackConfigId} THEN #{item.secondLevelCode}
ELSE second_level_code END,
second_level_name = CASE
WHEN competition_track_config_id = #{item.competitionTrackConfigId} THEN #{item.secondLevelName}
ELSE second_level_name END,
update_time = NOW(), version = version + 1
WHERE competition_track_config_id IN
#{item.competitionTrackConfigId}
